# Cart: volley -- "MASS VOLLEY"
#
# A prototype. You have no gun. You aim a horde of corpses you have already
# raised, and the horde is launched at whatever is under the crosshair.
#
#   ./bin/run --cart volley
#
# Controls: arrows / WASD / stick to move the caster, MOUSE to aim,
# SPACE (or A / left click) to launch the horde. ESC is not used.
#
# Zero art. Every texture is generated by auto_sprite at boot.
#
# NOTE ON THE STAGE: this cart draws in screen space and sizes its stage to the
# window, because the whole battlefield has to be legible at once -- reading
# where the horde is and what is left to kill is the decision. There is no
# camera.follow, so the camera only ever contributes the zoom punch.
TITLE = 'mass volley'

class Volley
  SPEED          = 5.0   # caster movement, px per tick
  HORDE          = 34    # corpses per volley at wave 1
  HORDE_MAX      = 52
  FIRE_COOLDOWN  = 30
  CORPSE_SPEED   = 7.4
  ATTRACT_PERIOD = 58    # ticks between auto-volleys while nobody is playing
  ATTRACT_FIRST  = 40    # ...and the first one, so the game is never idle

  # The corpse pose set. An entity cycles its own index into this array every
  # tick, so 36 corpses sharing 5 textures and 3 sizes read as a swarm of
  # individuals rather than as one rectangle moving.
  CORPSE_FRAMES = %i[corpse_a corpse_b corpse_c corpse_d corpse_e].freeze

  def setup
    auto_sprite :caster, 22, 30, :accent,  :frame

    # The horde. Deliberately varied in silhouette, not just in colour.
    auto_sprite :corpse_a, 18, 22, :good,    :circle
    auto_sprite :corpse_b, 20, 26, :accent2, :frame
    auto_sprite :corpse_c, 15, 17, :good,    :ring
    auto_sprite :corpse_d, 23, 20, :good,    :checker
    auto_sprite :corpse_e, 17, 24, :accent2, :solid

    auto_sprite :target_shell, 58, 58, :warn, :ring
    auto_sprite :target_core,  40, 40, :bad,  :circle

    auto_sprite :bloom_ring, 64, 64, :good,   :ring
    auto_sprite :spark,      7,  7,  :warn,  :circle
    auto_sprite :grave,      16, 14, :panel, :frame

    scene :play, PlayScene
    goto :play
  end

  class PlayScene
    def enter
      Console.entities.clear
      Console.tweens.clear
      Console.anim.stop_all
      camera.follow nil
      camera.bounds = nil

      @sw = screen[:w]
      @sh = screen[:h]

      # The zoom punch tweens this Hash rather than the camera object itself,
      # because Tween drives its target with @target[:key] (tween.rb:80) and
      # Console::Camera has no #[]. render copies it onto camera.zoom.
      @cam = { z: 1.0 }
      @zoom_tween = nil

      @t = 0
      @fire_cd = Volley::ATTRACT_FIRST
      @targets = []
      @lock = nil
      @aim_x = @sw * 0.5
      @aim_y = @sh * 0.5
      @orbit = 0.0

      # Attract mode: the game plays itself until a human touches it, so a
      # headless run still shows the volley instead of an empty stage.
      @attract = true
      @ptr_x = nil
      @ptr_y = nil

      d = scene_data
      d[:kills] = 0
      d[:shots] = 0
      d[:wave] = 1
      d[:spawn_cd] = 1

      @hero = spawn :hero, kind: :hero,
                    x: (@sw * 0.5) - 11, y: (@sh * 0.32) - 15,
                    w: 22, h: 30, sprite: :caster

      spawn_target
    end

    def update
      @t += 1
      d = scene_data
      # mruby's `/` always returns a Float, so an unrounded wave would make
      # count.times below explode. Keep every count an Integer.
      d[:wave] = 1 + ((@t / 480).to_i)

      read_input_state
      move_caster
      aim
      maybe_fire
      escalate
      step_corpses
      step_targets
      step_sparks
      step_blooms
    end

    # Render is the hook. Never define `draw` -- it shadows the console's own
    # rendering object and the screen silently goes blank.
    def render
      background :panel_d
      draw_graves

      # The zoom punch is tweened into a plain Hash (@cam) because Tween drives
      # its target with @target[:key] and Console::Camera has no #[]. Copy it
      # onto the camera, and let the ENGINE apply shake, zoom and offset.
      camera.zoom = @cam[:z]

      # Everything inside apply is world space and the engine transforms it.
      # Do not also transform it by hand: that is a double transform, and it
      # fails silently with no error.
      camera.apply do
        each_entity(:corpse) { |e| draw_entity e }
        each_entity(:target) do |e|
          draw_entity e
          # A ring alone reads as an empty hoop; the core is what makes a target
          # look like something worth hitting.
          draw.sprite path: :target_core, x: e[:x], y: e[:y], w: 40, h: 40,
                      color: :bad, alpha: 190
        end
        each_entity(:spark) { |e| draw_entity e }
        each_entity(:bloom) { |e| draw_entity e }
        draw_entity @hero
        draw_crosshair
      end

      hud
    end

    # ---------------------------------------------------------------- input

    def read_input_state
      p = input.pointer
      moved = false
      if p
        moved = @ptr_x && (@ptr_x != p[:x] || @ptr_y != p[:y])
        @ptr_x = p[:x]
        @ptr_y = p[:y]
      end
      v = input.axis_vector
      active = moved || input.pointer_pressed? ||
               input.pressed?(:accept) || v[:x] != 0 || v[:y] != 0
      @attract = false if active
    end

    # The caster moves under its own axis vector, every tick, always.
    # Attract mode substitutes a synthetic vector into the SAME integration
    # path, so a headless screenshot still demonstrates real movement.
    def move_caster
      v = desired_vector
      @hero[:x] = (@hero[:x] + (v[:x] * Volley::SPEED))
                   .clamp(0, @sw - @hero[:w])
      @hero[:y] = (@hero[:y] + (v[:y] * Volley::SPEED))
                   .clamp(0, @sh - @hero[:h])
    end

    def desired_vector
      real = input.axis_vector
      return real if real[:x] != 0 || real[:y] != 0
      return real unless @attract

      @orbit += 0.013
      tx = (@sw * 0.5) + (Math.cos(@orbit) * @sw * 0.26)
      ty = (@sh * 0.5) + (Math.sin(@orbit * 1.3) * @sh * 0.24)
      dx = tx - @hero[:x]
      dy = ty - @hero[:y]
      len = Math.sqrt((dx * dx) + (dy * dy))
      return { x: 0.0, y: 0.0 } if len < 1.0
      { x: dx / len, y: dy / len }
    end

    def aim
      # The aim point must exist BEFORE pick_target measures distance to it.
      if @attract
        first = @targets.first
        @aim_x = first ? first[:x] + (first[:w] / 2.0) : (@sw * 0.5)
        @aim_y = first ? first[:y] + (first[:h] / 2.0) : (@sh * 0.5)
      else
        p = input.pointer
        @aim_x = p ? p[:x] : (@sw * 0.5)
        @aim_y = p ? p[:y] : (@sh * 0.5)
      end
      @lock = pick_target
    end

    def pick_target
      return nil if @targets.empty?
      best = nil
      best_d = nil
      @targets.each do |t|
        dx = (t[:x] + (t[:w] / 2.0)) - @aim_x
        dy = (t[:y] + (t[:h] / 2.0)) - @aim_y
        d = (dx * dx) + (dy * dy)
        if best_d.nil? || d < best_d
          best = t
          best_d = d
        end
      end
      best
    end

    # ------------------------------------------------------------ the volley

    def maybe_fire
      @fire_cd -= 1
      return if @fire_cd > 0

      trigger = input.pressed?(:accept) || input.pressed?(:action_2) ||
                input.pointer_pressed?
      trigger = true if @attract && (@t % Volley::ATTRACT_PERIOD).zero?

      return unless trigger
      @lock = pick_target || @targets.first
      return if @lock.nil?
      launch_volley
      @fire_cd = Volley::FIRE_COOLDOWN
    end

    # THE IMPACT MOMENT. Thirty-plus corpses leave the ground at the caster in
    # a tight ring, hold for a beat, then peel off and converge on the lock.
    def launch_volley
      px = @hero[:x] + (@hero[:w] / 2.0)
      py = @hero[:y] + (@hero[:h] / 2.0)

      count = Volley::HORDE + ((scene_data[:wave] - 1) * 3)
      count = Volley::HORDE_MAX if count > Volley::HORDE_MAX
      count = count.to_i

      count.times do |i|
        # Golden-angle spacing so the ring has no clumps and no gaps.
        a = (i * 2.39996) % 6.28318
        r = 24 + rand_between(0, 18)
        spawn :corpse, kind: :corpse,
                     x: px + (Math.cos(a) * r) - 9,
                     y: py + (Math.sin(a) * r) - 9,
                     w: rand_between(13, 21).to_i,
                     h: rand_between(15, 24).to_i,
                     sprite_frames: Volley::CORPSE_FRAMES,
                     sprite_frame: i % Volley::CORPSE_FRAMES.size,
                     tint: chance(0.25) ? :accent2 : :good,
                     speed: Volley::CORPSE_SPEED * rand_between(0.86, 1.22),
                     delay: i % 16,
                     age: 0
      end

      bloom px, py, 3
      punch!
      sfx :volley
      scene_data[:shots] += 1
    end

    # Shake plus a zoom punch. The zoom lives in @cam because Console::Tween
    # drives @target[:key] and Console::Camera has no #[] -- tweening the camera
    # object itself raises NoMethodError.
    def punch!
      camera.shake 10, 16
      tweens.cancel_tween @zoom_tween if @zoom_tween
      @cam[:z] = 1.0
      @zoom_tween = tween @cam, :z, to: 0.85, in: 7, ease: :out,
                                 yoyo: true, loops: 2
      sfx :launch
    end

    def bloom(x, y, rings)
      rings.times do |i|
        r = 190 + (i * 40)
        hold = 18 + (i * 6)
        b = spawn :bloom, kind: :bloom,
                         x: x - 10, y: y - 10, w: 20, h: 20,
                         sprite: :bloom_ring, tint: :good, alpha: 220
        tween b, :w, to: r, in: hold, ease: :out
        tween b, :h, to: r, in: hold, ease: :out
        tween b, :alpha, to: 0, in: hold, ease: :in
        after hold + 2 do
          despawn b
        end
      end
    end

    # ------------------------------------------------------------- stepping

    def step_corpses
      spent = []
      damage = 0
      last_tgt = nil

      each_entity(:corpse) do |c|
        # Per-entity frame cycle. Entities seeded with different indices, so
        # the horde shimmers instead of blinking as one body.
        c[:sprite_frame] = ((c[:sprite_frame] || 0) + 1) % Volley::CORPSE_FRAMES.size

        if c[:delay] > 0
          c[:delay] -= 1
          next
        end

        tgt = @lock || pick_target
        if tgt.nil?
          spent << c
          next
        end

        # Homing is computed here rather than via EntityStore#toward: that
        # helper mixes Math.sin/cos with Geometry.angle, whose angle convention
        # does not line up with its own vx/vy axes in this engine -- the horde
        # sails away from its target. Four lines of maths, no ambiguity.
        cx = c[:x] + (c[:w] / 2.0)
        cy = c[:y] + (c[:h] / 2.0)
        tx = tgt[:x] + (tgt[:w] / 2.0)
        ty = tgt[:y] + (tgt[:h] / 2.0)
        dx = tx - cx
        dy = ty - cy
        len = Math.sqrt((dx * dx) + (dy * dy))

        if len <= 20.0
          spent << c
          damage += 1
          last_tgt = tgt
        else
          sp = c[:speed]
          move c, vx: (dx / len) * sp, vy: (dy / len) * sp
          c[:age] += 1
          spent << c if c[:age] > 320
        end
      end

      spent.each { |c| despawn c }
      # Damage lands after the walk: hit_target can despawn the target and
      # mutate @targets, which would invalidate an iteration in flight.
      hit_target(last_tgt, damage) if damage > 0 && last_tgt
    end

    def step_targets
      each_entity(:target) do |t|
        t[:x] += t[:vx]
        t[:y] += t[:vy]
        t[:wob] = (t[:wob] || 0) + 0.09
        # Bounce off the stage so a target never drifts out of play.
        if t[:x] < 20
          t[:x] = 20; t[:vx] = -t[:vx]
        elsif t[:x] > @sw - 20 - t[:w]
          t[:x] = @sw - 20 - t[:w]; t[:vx] = -t[:vx]
        end
        if t[:y] < 70
          t[:y] = 70; t[:vy] = -t[:vy]
        elsif t[:y] > @sh - 20 - t[:h]
          t[:y] = @sh - 20 - t[:h]; t[:vy] = -t[:vy]
        end
      end
    end

    def step_sparks
      each_entity(:spark) do |s|
        move s, vx: s[:vx], vy: s[:vy]
        s[:life] -= 1
      end
      despawn_if { |s| s[:kind] == :spark && s[:life] <= 0 }
    end

    def step_blooms
      # Tweens drive these; they only need culling once their tween lands.
      despawn_if { |b| b[:kind] == :bloom && (b[:alpha] || 0) <= 0 }
    end

    # ------------------------------------------------------------ escalation

    # Targets arrive faster over time, and each is tougher than the last.
    def escalate
      d = scene_data
      d[:spawn_cd] -= 1
      return unless d[:spawn_cd] <= 0
      return if entity_count(:target) >= 5
      spawn_target
      gap = 150 - (d[:wave] * 12)
      gap = 46 if gap < 46
      d[:spawn_cd] = gap
    end

    def spawn_target
      w = 44
      h = 44
      hp = 8 + (scene_data[:wave] * 5)
      t = spawn :target, kind: :target,
                     x: rand_between(60, @sw - 120).to_i,
                     y: rand_between(110, @sh - 140).to_i,
                     w: w, h: h,
                     sprite: :target_shell,
                     hp: hp, max_hp: hp,
                     vx: rand_between(-0.9, 0.9),
                     vy: rand_between(-0.7, 0.7)
      @targets << t
      t
    end

    def hit_target(tgt, amount = 1)
      return if tgt.nil?
      tgt[:hp] -= amount
      cx = tgt[:x] + (tgt[:w] / 2.0)
      cy = tgt[:y] + (tgt[:h] / 2.0)
      burst cx, cy, :good, 3 * amount

      if tgt[:hp] <= 0
        burst cx, cy, :warn, 18
        camera.shake 6, 12
        @targets.delete tgt
        despawn tgt
        scene_data[:kills] += 1
        sfx :explode
        @lock = nil if @lock == tgt
        after 16 { spawn_target }
      else
        camera.shake 2, 5
        sfx :hit
      end
    end

    def burst(x, y, color, count)
      count.times do
        spawn :spark, kind: :spark,
                     x: x, y: y, w: 7, h: 7, sprite: :spark,
                     vx: rand_between(-3, 3), vy: rand_between(-3, 3),
                     tint: color, life: 26
      end
    end

    # ---------------------------------------------------------------- draw

    def draw_graves
      x = 40.0
      i = 0
      while x < @sw
        y = @sh * 0.12 + ((i % 3) * 26)
        draw.sprite path: :grave, x: x, y: y, w: 16, h: 14
        x += 118 + ((i % 4) * 23)
        i += 1
      end
      draw.rect x: 0, y: 0, w: @sw, h: 40, color: :black, alpha: 90
    end

    # The tether: caster to crosshair, so the aim is legible at a glance.
    def draw_crosshair
      hx = @aim_x
      hy = @aim_y
      px = @hero[:x]
      py = @hero[:y]

      draw.line px, py, hx, hy, :muted, 1

      r = 16
      draw.border({ x: hx - r, y: hy - r, w: r * 2, h: r * 2,
                    color: :warn, alpha: 230 }, 2)
      draw.rect x: hx - 1, y: hy - 1, w: 2, h: 2, color: :warn

      # The lock's health ring, drawn as a shrinking bar under the crosshair.
      return if @lock.nil?
      pct = @lock[:hp].to_f / @lock[:max_hp].to_f
      pct = 0.0 if pct < 0.0
      draw.rect x: hx - 30, y: hy - r - 12, w: 60, h: 5, color: :black, alpha: 170
      draw.rect x: hx - 30, y: hy - r - 12, w: 60 * pct, h: 5, color: :bad
    end

    def hud
      d = scene_data
      live = entity_count(:corpse)
      draw.within strip(0, 46) do
        draw.rect place: { x: 0, y: 0, w: 1, h: 1 }, color: :black, alpha: 175
        draw.text "KILLS #{d[:kills]}   WAVE #{d[:wave]}",
                  place: { x: 0.015, y: 0.5, anchor_y: 0.5 }, color: :text
        draw.text "VOLLEYS #{d[:shots]}   IN FLIGHT #{live}",
                  place: { x: 0.30, y: 0.5, anchor_x: 0.0, anchor_y: 0.5 },
                  color: :muted
        draw.text 'ARROWS move    MOUSE aim    SPACE launch',
                  place: { x: 0.985, y: 0.5, anchor_x: 1.0, anchor_y: 0.5 },
                  color: :muted
      end
      if @attract
        draw.text 'ATTRACT MODE - move or click to take over',
                  x: @sw / 2.0, y: top(56), anchor_x: 0.5,
                  size_px: 16, color: :warn
      end
    end
  end
end

# ---------------------------------------------------------------------------
# LIBRARY BEHAVIOUR THIS CART DEPENDS ON
#
# 1. THE CAMERA WORKS. `resolve` applies the transform, so anything drawn inside
#    camera.apply is world space and receives shake, zoom and offset for free.
#    Do NOT also transform it by hand: that is a double transform, and it fails
#    silently with no error. (Before 2026-10-18 the transform had no call sites,
#    the camera did nothing, and every cart carried its own hand-rolled `blit`.
#    That is gone, along with the blit in this file.)
#
# 2. The zoom punch tweens the plain Hash @cam and render copies it onto
#    camera.zoom. Console::Camera now answers [] / []=, so
#    `tween camera, :zoom, ...` would work too; either is fine.
#
# 3. Homing computes dx/dy/len by hand. EntityStore#toward (now also a bare
#    `toward` call) used to aim with sin/cos swapped against Geometry.angle and
#    sent homing entities AWAY from their lock; it is fixed, so new carts can
#    use it.
#
# 4. EntityStore holds no velocity and no lifetime of its own; `move` is manual
#    and life is decremented by hand (see step_sparks).
# ---------------------------------------------------------------------------